floater.floater.string:
// Every kind of token, to see the colors by
#define GREETING "Hello"
integer count = 0;
string  name  = "Avatar\n";

float half(integer n)
{
    return (float)n / 2.0;
}

default
{
    state_entry()
    {
        llSay(PUBLIC_CHANNEL, GREETING + " " + name);
        llSetTimerEvent(half(count) + 1.0);
        vector where = <1.0, 0.0, 0.5>;
        @again;
        if (++count < 3) jump again;
        llSound("", 1.0, TRUE, FALSE);
        state other;
    }
}
